window.__OPENSTAX_PHYSICS__[20] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.872Z","number":20,"code":"ch20","slug":"magnetism","title":"Magnetism","titleVi":"Từ Trường & Cảm Ứng Điện Từ (Magnetism)","sections":[{"uid":"hsphys.ch20.sec00","moduleId":"m54460","number":"20.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch20.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["You may have encountered magnets for the first time as a small child playing with magnetic toys or refrigerator magnets. At the time, you likely noticed that two magnets that repulse each other will attract each other if you flip one of them around. The force that acts across the air gaps between magnets is the same force that creates wonders such as the Aurora Borealis. In fact, magnetic effects pervade our lives in myriad ways, from electric motors to medical imaging and computer memory. In this chapter, we introduce magnets and learn how they work and how magnetic fields and electric currents interact."],"figures":[{"sourceId":"fs-id1167064876028","filename":"CNX_HSPhysics_20_00_Aurora.jpg","relativePath":"media/CNX_HSPhysics_20_00_Aurora.jpg","alt":"The Aurora Borealis."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch20.sec01","moduleId":"m54465","number":"20.1","slug":"magnetic-fields-field-lines-and-force","title":"Magnetic Fields, Field Lines, and Force","isIntroduction":false,"learningObjectives":["Summarize properties of magnets and describe how some nonmagnetic materials can become magnetized","Describe and interpret drawings of magnetic fields around permanent magnets and current-carrying wires","Calculate the magnitude and direction of magnetic force in a magnetic field and the force on a current-carrying wire in a magnetic field"],"bilingualGuide":{"notebookSummaryVi":"Từ trường (B, đơn vị Tesla), đường sức từ, Quy tắc bàn tay phải và Lực từ tác dụng lên điện tích chuyển động (F = qvB sinθ) & dây dẫn (F = ILB sinθ).","wordProblemCues":[{"phraseEn":"magnetic force on moving charge","meaningVi":"Lực Lorentz tác dụng lên hạt mang điện","mathNotation":"F = qvB sinθ"}],"commonTrapsVi":["Nếu điện tích ĐỨNG YÊN (v = 0) hoặc bay SONG SONG đường sức từ (θ = 0° hoặc 180°) thì Lực từ F = 0!"]},"keyEquations":[{"name":"the magnitude of the force on an electric charge","formula":"\\(F = qvBsin\\theta\\)"},{"name":"the force on a wire carrying current","formula":"\\(F = IℓBsin\\theta\\)"},{"name":"the magnitude of the magnetic field created by a long, straight current-carrying wire","formula":"\\({B}_{\\text{straight}\\text{wire}} = \\frac{{\\mu}_{0}I}{2\\pi r}\\)"},{"name":"the magnitude of the magnetic field inside a solenoid","formula":"\\({B}_{\\text{solenoid}} = {\\mu}_{0}\\frac{NI}{ℓ}\\)"}],"subsections":[{"uid":"hsphys.ch20.sec01.sub01","title":"Magnets and Magnetization","summaryVi":null,"paragraphs":["People have been aware of magnets and magnetism for thousands of years. The earliest records date back to ancient times, particularly in the region of Asia Minor called Magnesia—the name of this region is the source of words like magnet . Magnetic rocks found in Magnesia, which is now part of western Turkey, stimulated interest during ancient times. When humans first discovered magnetic rocks, they likely found that certain parts of these rocks attracted bits of iron or other magnetic rocks more strongly than other parts. These areas are called the poles of a magnet. A magnetic pole is the part of a magnet that exerts the strongest force on other magnets or magnetic material, such as iron. For example, the poles of the bar magnet shown in [Figure 20.1] are where the paper clips are concentrated.","If a bar magnet is suspended so that it rotates freely, one pole of the magnet will always turn toward the north, with the opposite pole facing south. This discovery led to the compass, which is simply a small, elongated magnet mounted so that it can rotate freely. An example of a compass is shown [Figure 20.1]. The pole of the magnet that orients northward is called the north pole , and the opposite pole of the magnet is called the south pole .","The discovery that one particular pole of a magnet orients northward, whereas the other pole orients southward allowed people to identify the north and south poles of any magnet. It was then noticed that the north poles of two different magnets repel each other, and likewise for the south poles. Conversely, the north pole of one magnet attracts the south pole of other magnets. This situation is analogous to that of electric charge, where like charges repel and unlike charges attract. In magnets, we simply replace charge with pole : Like poles repel and unlike poles attract. This is summarized in [Figure 20.1], which shows how the force between magnets depends on their relative orientation.","Consider again the fact that the pole of a magnet that orients northward is called the north pole of the magnet. If unlike poles attract, then the magnetic pole of Earth that is close to the geographic North Pole must be a magnetic south pole! Likewise, the magnetic pole of Earth that is close to the geographic South Pole must be a magnetic north pole. This situation is depicted in [Figure 20.1], in which Earth is represented as containing a giant internal bar magnet with its magnetic south pole at the geographic North Pole and vice versa. If we were to somehow suspend a giant bar magnet in space near Earth, then the north pole of the space magnet would be attracted to the south pole of Earth’s internal magnet. This is in essence what happens with a compass needle: Its magnetic north pole is attracted to the magnet south pole of Earth’s internal magnet.","What happens if you cut a bar magnet in half? Do you obtain one magnet with two south poles and one magnet with two north poles? The answer is no: Each half of the bar magnet has a north pole and a south pole. You can even continue cutting each piece of the bar magnet in half, and you will always obtain a new, smaller magnet with two opposite poles. As shown in [Figure 20.1], you can continue this process down to the atomic scale, and you will find that even the smallest particles that behave as magnets have two opposite poles. In fact, no experiment has ever found any object with a single magnetic pole, from the smallest subatomic particle such as electrons to the largest objects in the universe such as stars. Because magnets always have two poles, they are referred to as magnetic dipoles — di means two . Below, we will see that magnetic dipoles have properties that are analogous to electric dipoles.","Only certain materials, such as iron, cobalt, nickel, and gadolinium, exhibit strong magnetic effects. Such materials are called ferromagnetic , after the Latin word ferrum for iron. Other materials exhibit weak magnetic effects, which are detectable only with sensitive instruments. Not only do ferromagnetic materials respond strongly to magnets—the way iron is attracted to magnets—but they can also be magnetized themselves—that is, they can be induced to be magnetic or made into permanent magnets ([Figure 20.1]). A permanent magnet is simply a material that retains its magnetic behavior for a long time, even when exposed to demagnetizing influences.","When a magnet is brought near a previously unmagnetized ferromagnetic material, it causes local magnetization of the material with unlike poles closest, as in the right side of [Figure 20.1]. This causes an attractive force, which is why unmagnetized iron is attracted to a magnet.","What happens on a microscopic scale is illustrated in Figure 7(a) . Regions within the material called domains act like small bar magnets. Within domains, the magnetic poles of individual atoms are aligned. Each atom acts like a tiny bar magnet. Domains are small and randomly oriented in an unmagnetized ferromagnetic object. In response to an external magnetic field, the domains may grow to millimeter size, aligning themselves, as shown in Figure 7(b) . This induced magnetization can be made permanent if the material is heated and then cooled, or simply tapped in the presence of other magnets.","Conversely, a permanent magnet can be demagnetized by hard blows or by heating it in the absence of another magnet. Increased thermal motion at higher temperature can disrupt and randomize the orientation and size of the domains. There is a well-defined temperature for ferromagnetic materials, which is called the Curie temperature , above which they cannot be magnetized. The Curie temperature for iron is 1,043 K (770 °C ), which is well above room temperature. There are several elements and alloys that have Curie temperatures much lower than room temperature and are ferromagnetic only below those temperatures."],"figures":[{"sourceId":"fs-id1167065866922","filename":"CNX_HSPhysics_20_01_magnets.jpg","relativePath":"media/CNX_HSPhysics_20_01_magnets.jpg","alt":"A bar magnet with paper clips attached to it."},{"sourceId":"fs-id1167064920660","filename":"CNX_HSPhysics_20_01_compass.jpg","relativePath":"media/CNX_HSPhysics_20_01_compass.jpg","alt":"A compass on a lanyard."},{"sourceId":"fs-id1167062400279","filename":"CNX_HSPhysics_20_01_magorien.jpg","relativePath":"media/CNX_HSPhysics_20_01_magorien.jpg","alt":"Bar magnets oriented in the same direction repel, whereas if they are oriented in the opposite direction of each other, they attract."},{"sourceId":"fs-id1167065944648","filename":"CNX_HSPhysics_20_01_Emagpole.jpg","relativePath":"media/CNX_HSPhysics_20_01_Emagpole.jpg","alt":"Earth depicted as a giant bar magnet whose magnetic north pole is at its geographic South Pole and vice versa."},{"sourceId":"fs-id1167065722174","filename":"CNX_HSPhysics_20_01_pairs.jpg","relativePath":"media/CNX_HSPhysics_20_01_pairs.jpg","alt":"A magnet cut into smaller and smaller sizes, all with a north and a south pole."},{"sourceId":"fs-id1167064989984","filename":"CNX_HSPhysics_20_01_magnetize.jpg","relativePath":"media/CNX_HSPhysics_20_01_magnetize.jpg","alt":"An iron bar is magnetized when heated and cooled (or tapped when cold) when placed between a magnet’s north and south poles."},{"sourceId":"fs-id1167062339335","filename":"CNX_HSPhysics_20_01_domains.jpg","relativePath":"media/CNX_HSPhysics_20_01_domains.jpg","alt":"Part (a) shows domains in an unmagnetized ferromagnetic material. Part (b) shows alignment of the domains when the material is magnetized."}],"tables":[]},{"uid":"hsphys.ch20.sec01.sub02","title":"Magnetic Fields","summaryVi":null,"paragraphs":["We have thus seen that forces can be applied between magnets and between magnets and ferromagnetic materials without any contact between the objects. This is reminiscent of electric forces, which also act over distances. Electric forces are described using the concept of the electric field, which is a force field around electric charges that describes the force on any other charge placed in the field. Likewise, a magnet creates a magnetic field around it that describes the force exerted on other magnets placed in the field. As with electric fields, the pictorial representation of magnetic field lines is very useful for visualizing the strength and direction of the magnetic field.","As shown in [Figure 20.1], the direction of magnetic field lines is defined to be the direction in which the north pole of a compass needle points. If you place a compass near the north pole of a magnet, the north pole of the compass needle will be repelled and point away from the magnet. Thus, the magnetic field lines point away from the north pole of a magnet and toward its south pole.","Magnetic field lines can be mapped out using a small compass. The compass is moved from point to point around a magnet, and at each point, a short line is drawn in the direction of the needle, as shown in [Figure 20.1]. Joining the lines together then reveals the path of the magnetic field line. Another way to visualize magnetic field lines is to sprinkle iron filings around a magnet. The filings will orient themselves along the magnetic field lines, forming a pattern such as that shown on the right in [Figure 20.1].","This simulation presents you with a bar magnet and a small compass. Begin by dragging the compass around the bar magnet to see in which direction the magnetic field points. Note that the strength of the magnetic field is represented by the brightness of the magnetic field icons in the grid pattern around the magnet. Use the magnetic field meter to check the field strength at several points around the bar magnet. You can also flip the polarity of the magnet, or place Earth on the image to see how the compass orients itself.","With the slider at the top right of the simulation window, set the magnetic field strength to 100 percent . Now use the magnetic field meter to answer the following question: Near the magnet, where is the magnetic field strongest and where is it weakest? Don’t forget to check inside the bar magnet.","When two magnets are brought close together, the magnetic field lines are perturbed, just as happens for electric field lines when two electric charges are brought together. Bringing two north poles together—or two south poles—will cause a repulsion, and the magnetic field lines will bend away from each other. This is shown in [Figure 20.1], which shows the magnetic field lines created by the two closely separated north poles of a bar magnet. When opposite poles of two magnets are brought together, the magnetic field lines join together and become denser between the poles. This situation is shown in [Figure 20.1].","Like the electric field, the magnetic field is stronger where the lines are denser. Thus, between the two north poles in [Figure 20.1], the magnetic field is very weak because the density of the magnetic field is almost zero. A compass placed at that point would essentially spin freely if we ignore Earth’s magnetic field. Conversely, the magnetic field lines between the north and south poles in [Figure 20.1] are very dense, indicating that the magnetic field is very strong in this region. A compass placed here would quickly align with the magnetic field and point toward the south pole on the right.","Note that magnets are not the only things that make magnetic fields. Early in the nineteenth century, people discovered that electrical currents cause magnetic effects. The first significant observation was by the Danish scientist Hans Christian Oersted (1777–1851), who found that a compass needle was deflected by a current-carrying wire. This was the first significant evidence that the movement of electric charges had any connection with magnets. An electromagnet is a device that uses electric current to make a magnetic field. These temporarily induced magnets are called electromagnets. Electromagnets are employed for everything from a wrecking yard crane that lifts scrapped cars to controlling the beam of a 90-km-circumference particle accelerator to the magnets in medical-imaging machines (see [Figure 20.1]).","The magnetic field created by an electric current in a long straight wire is shown in [Figure 20.1]. The magnetic field lines form concentric circles around the wire. The direction of the magnetic field can be determined using the right-hand rule . This rule shows up in several places in the study of electricity and magnetism. Applied to a straight current-carrying wire, the right-hand rule says that, with your right thumb pointed in the direction of the current, the magnetic field will be in the direction in which your right fingers curl, as shown in [Figure 20.1]. If the wire is very long compared to the distance r from the wire, the strength B of the magnetic field is given by","where I is the current in the wire in amperes. The SI unit for magnetic field is the tesla (T). The symbol \\({\\mu}_{0}\\) —read “mu-zero”—is a constant called the “permeability of free space” and is given by","Now imagine winding a wire around a cylinder with the cylinder then removed. The result is a wire coil, as shown in [Figure 20.1]. This is called a solenoid . To find the direction of the magnetic field produced by a solenoid, apply the right-hand rule to several points on the coil. You should be able to convince yourself that, inside the coil, the magnetic field points from left to right. In fact, another application of the right-hand rule is to curl your right-hand fingers around the coil in the direction in which the current flows. Your right thumb then points in the direction of the magnetic field inside the coil: left to right in this case.","Each loop of wire contributes to the magnetic field inside the solenoid. Because the magnetic field lines must form closed loops, the field lines close the loop outside the solenoid. The magnetic field lines are much denser inside the solenoid than outside the solenoid. The resulting magnetic field looks very much like that of a bar magnet, as shown in [Figure 20.1]. The magnetic field strength deep inside a solenoid is","where N is the number of wire loops in the solenoid and \\(ℓ\\) is the length of the solenoid.","Use this simulation to visualize the magnetic field made from a solenoid. Be sure to click on the tab that says Electromagnet. You can drive AC or DC current through the solenoid by choosing the appropriate current source. Use the field meter to measure the strength of the magnetic field and then change the number of loops in the solenoid to see how this affects the magnetic field strength."],"figures":[{"sourceId":"fs-id1167066199355","filename":"CNX_HSPhysics_20_01_magfield.jpg","relativePath":"media/CNX_HSPhysics_20_01_magfield.jpg","alt":"Two bar magnets with magnetic field lines emanating from them in complete loops."},{"sourceId":"fs-id1167064901815","filename":"CNX_HSPhysics_20_01_drawMFLs.jpg","relativePath":"media/CNX_HSPhysics_20_01_drawMFLs.jpg","alt":"Parts (a) through (d) show the steps in drawing magnetic field lines using a small compass that is moved from point to point around a magnet; the image on the right shows iron filings sprinkled around a magnet."},{"sourceId":"fs-id1167064697081","filename":"CNX_HSPhysics_20_01_ARMFLs.jpg","relativePath":"media/CNX_HSPhysics_20_01_ARMFLs.jpg","alt":"Part (a) shows the field lines when two north poles are brought close together. Part (b) shows the field lines when opposite poles are brought together; they become denser."},{"sourceId":"fs-id1167065881460","filename":"CNX_HSPhysics_20_01_medemag.jpg","relativePath":"media/CNX_HSPhysics_20_01_medemag.jpg","alt":"A modern MRI machine in a medical room, designed with a comforting, illuminated ceiling panel featuring vibrant yellow and purple flowers to soothe patients during scans."},{"sourceId":"fs-id1167064791947","filename":"CNX_HSPhysics_20_01_RHR.jpg","relativePath":"media/CNX_HSPhysics_20_01_RHR.jpg","alt":"Demonstration of the right-hand rule, where the thumb points in the direction of the current and the fingers curl in the direction of the magnetic field."},{"sourceId":"fs-id1167065793310","filename":"CNX_HSPhysics_20_01_wirecoil.jpg","relativePath":"media/CNX_HSPhysics_20_01_wirecoil.jpg","alt":"A wire coil with current running through it. The magnetic field generated is shown by a red arrow."},{"sourceId":"fs-id1167065952491","filename":"CNX_HSPhysics_20_01_solvsmag.jpg","relativePath":"media/CNX_HSPhysics_20_01_solvsmag.jpg","alt":"Part (a) shows iron filings around a solenoid; part (b) shows iron filings around a bar magnet."}],"tables":[]},{"uid":"hsphys.ch20.sec01.sub03","title":"Magnetic Force","summaryVi":null,"paragraphs":["If a moving electric charge, that is electric current, produces a magnetic field that can exert a force on another magnet, then the reverse should be true by Newton’s third law. In other words, a charge moving through the magnetic field produced by another object should experience a force—and this is exactly what we find. As a concrete example, consider [Figure 20.1], which shows a charge q moving with velocity \\(\\vec{v}\\) through a magnetic field \\(\\vec{B}\\) between the poles of a permanent magnet. The magnitude F of the force experienced by this charge is","where \\(\\theta\\) is the angle between the velocity of the charge and the magnetic field. From this equation, we can see that the SI unit of magnetic field, the Tesla, is the magnetic field required to produce a 1 N force on a 1 C charge moving at 1 m/s in a direction perpendicular to the field and equivalent to the following: \\(\\text{T} = \\frac{(N \\cdot \\text{s})}{(\\text{C} \\cdot \\text{m})}\\).","The direction of the force may be found by using another version of the right-hand rule: First, we join the tails of the velocity vector and a magnetic field vector, as shown in step 1 of [Figure 20.1]. We then curl our right fingers from \\(\\vec{v}\\) to \\(\\vec{B}\\), as indicated in step (2) of [Figure 20.1]. The direction in which the right thumb points is the direction of the force. For the charge in [Figure 20.1], we find that the force is directed into the page.","Note that the factor \\(sin\\theta\\) in the equation \\(F = qvBsin\\theta\\)\nmeans that zero force is applied on a charge that moves parallel to a magnetic field because \\(\\theta = 0\\) and \\(sin0 = 0\\) . The maximum force a charge can experience is when it moves perpendicular to the magnetic field, because \\(\\theta = 90°\\)\nand \\(sin90° = 1\\,\\text{.}\\)","Instead of a single charge moving through a magnetic field, consider now a steady current I moving through a straight wire. If we place this wire in a uniform magnetic field, as shown in [Figure 20.1], what is the force on the wire or, more precisely, on the electrons in the wire? An electric current involves charges that move. If the charges q move a distance \\(ℓ\\) in a time t , then their speed is \\(v = ℓ/t\\text{.}\\) Inserting this into the equation \\(F = qvBsin\\theta\\) gives","The factor q / t in this equation is nothing more than the current in the wire. Thus, using \\(I = q/t\\), we obtain","This equation gives the force on a straight current-carrying wire of length \\(ℓ\\) in a magnetic field of strength B . The angle \\(\\theta\\) is the angle between the current vector and the magnetic field vector. Note that \\(ℓ\\) is the length of wire that is in the magnetic field and for which \\(\\theta \\ne 0\\,\\text{,}\\) as shown in [Figure 20.1].","The direction of the force is determined in the same way as for a single charge. Curl your right fingers from the vector for I to the vector for B , and your right thumb will point in the direction of the force on the wire. For the wire shown in [Figure 20.1], the force is directed into the page.","Throughout this section, you may have noticed the symmetries between magnetic effects and electric effects. These effects all fall under the umbrella of electromagnetism , which is the study of electric and magnetic phenomena. We have seen that electric charges produce electric fields, and moving electric charges produce magnetic fields. A magnetic dipole produces a magnetic field, and, as we will see in the next section, moving magnetic dipoles produce an electric field. Thus, electricity and magnetism are two intimately related and symmetric phenomena."],"figures":[{"sourceId":"fs-id1167062469211","filename":"CNX_HSPhysics_20_01_qinB.jpg","relativePath":"media/CNX_HSPhysics_20_01_qinB.jpg","alt":"Part (a) shows a proton moving in a uniform magnetic field. Part (b) outlines the steps of the right-hand rule."},{"sourceId":"fs-id1167062325875","filename":"CNX_HSPhysics_20_01_wireinB.jpg","relativePath":"media/CNX_HSPhysics_20_01_wireinB.jpg","alt":"A current-carrying wire in a magnetic field, with force acting on the wire going into the page."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch20.sec01.ex01","number":"20.1.1","title":"Trajectory of Electron in Magnetic Field","problem":"A proton enters a region of constant magnetic field, as shown in [Figure 20.1]. The magnetic field is coming out of the page. If the electron is moving at \\(3.0\\, \\times \\,{10}^{6}\\text{m/s}\\) and the magnetic field strength is 2.0 T, what is the magnitude and direction of the force on the proton?\nA proton enters a region of uniform magnetic field. The magnetic field is coming out of the page—the circles with dots represent vector arrow heads coming out of the page.","problemImages":[{"sourceId":"fs-id1167065871077","filename":"CNX_HSPhysics_20_01_protinB.jpg","relativePath":"media/CNX_HSPhysics_20_01_protinB.jpg","alt":"A proton dot enters (green arrow) a magnetic field (depicted as circles with dots)."}],"strategy":"Use the equation \\(F = qvBsin\\theta\\) to find the magnitude of the force on the proton. The angle between the magnetic field vectors and the velocity vector of the proton is \\(90°\\,\\text{.}\\) The direction of the force may be found by using the right-hand rule.","solution":"The charge of the proton is \\(q = 1.60\\, \\times \\,{10}^{-19}\\text{C}\\) . Entering this value and the given velocity and magnetic field strength into the equation \\(F = qvBsin\\theta\\) gives\n\\(F = qvBsin\\theta = (1.60\\, \\times \\,{10}^{-19}\\text{C})(3.0\\, \\times \\,{10}^{6}\\text{m/s})(2.0\\,\\text{T})sin(90°) = 9.6\\, \\times \\,{10}^{-13}\\text{N.}\\) To find the direction of the force, first join the velocity vector end to end with the magnetic field vector, as shown in [Figure 20.1]. Now place your right hand so that your fingers point in the direction of the velocity and curl them upward toward the magnetic field vector. The force is in the direction in which your thumb points. In this case, the force is downward in the plane of the paper in the \\(\\bar{z}\\) -direction, as shown in [Figure 20.1].\nThe velocity vector and a magnetic field vector from [Figure 20.1] are placed end to end. A right hand is shown with the fingers curling up from the velocity vector toward the magnetic field vector. The thumb points in the direction of the resulting force, which is the \\(\\bar{z}\\) -direction in this case.\nThus, combining the magnitude and the direction, we find that the force on the proton is \\((9.6\\, \\times \\,{10}^{-13}\\text{N})\\bar{z}\\text{.}\\)","solutionImages":[{"sourceId":"fs-id1167064927243","filename":"CNX_HSPhysics_20_01_RHcurl.jpg","relativePath":"media/CNX_HSPhysics_20_01_RHcurl.jpg","alt":"The right-hand rule depicted with an actual hand showing a velocity vector and magnetic field, with the thumb pointing in the direction of the resulting force."}],"solutionTables":[],"discussion":"This seems like a very small force. However, the proton has a mass of \\(1.67\\, \\times \\,{10}^{-27}\\text{kg}\\), so its acceleration is \\(a = \\frac{F}{m} = \\frac{9.6\\, \\times \\,{10}^{-13}\\text{N}}{1.67\\, \\times \\,{10}^{-27}\\text{kg}} = 5.7\\, \\times \\,{10}^{14}{\\text{m/s}}^{\\text{2}}\\), or about ten thousand billion times the acceleration due to gravity!\nWe found that the proton’s initial acceleration as it enters the magnetic field is downward in the plane of the page. Notice that, as the proton accelerates, its velocity remains perpendicular to the magnetic field, so the magnitude of the force does not change. In addition, because of the right-hand rule, the direction of the force remains perpendicular to the velocity. This force is nothing more than a centripetal force: It has a constant magnitude and is always perpendicular to the velocity. Thus, the magnitude of the velocity does not change, and the proton executes circular motion. The radius of this circle may be found by using the kinematics relationship.\n\\(F = ma = m\\frac{{v}^{2}}{r}a = \\frac{{v}^{2}}{r}r = \\frac{{v}^{2}}{a} = \\frac{{(3.0\\, \\times \\,{10}^{6}\\text{m/s})}^{2}}{5.7\\, \\times \\,{10}^{14}{\\text{m/s}}^{\\text{2}}} = 1.6\\,\\text{cm}\\)\nThe path of the proton in the magnetic field is shown in [Figure 20.1].\nWhen traveling perpendicular to a constant magnetic field, a charged particle will execute circular motion, as shown here for a proton."},{"uid":"hsphys.ch20.sec01.ex02","number":"20.1.2","title":"Wire with Current in Magnetic Field","problem":"Now suppose we run a wire through the uniform magnetic field from the previous example, as shown. If the wire carries a current of 1.5 A in the \\(\\bar{y}\\) -direction, and the region with magnetic field is 4.0 cm long, what is the force on the wire?","problemImages":[{"sourceId":"fs-id1167062359077","filename":"CNX_HSPhysics_20_01_wireinB2_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_wireinB2_img.jpg","alt":"Insertion of a wire into a magnetic field from the previous example."}],"strategy":"Use equation \\(F = IℓBsin\\theta\\) to find the magnitude of the force on the wire. The length of the wire inside the magnetic field is 4.0 cm, and the angle between the current direction and the magnetic field direction is 90°. To find the direction of the force, use the right-hand rule as explained just after the equation \\(F = IℓBsin\\theta \\text{.}\\)","solution":"Insert the given values into equation \\(F = IℓBsin\\theta\\) to find the magnitude of the force\n\\(F = IℓBsin\\theta = (1.5\\,\\text{A})(0.040\\,\\text{m})(2.0\\,\\text{T}) = 0.12\\,\\text{N.}\\) To find the direction of the force, begin by placing the current vector end to end with a vector for the magnetic field. The result is as shown in the figure in the previous Worked Example with \\(\\vec{v}\\) replaced by \\(\\vec{I}\\) . Curl your right-hand fingers from \\(\\vec{I}\\) to \\(\\vec{B}\\) and your right thumb points down the page, again as shown in the figure in the previous Worked Example. Thus, the direction of the force is in the \\(\\bar{x}\\) -direction. The complete force is thus \\((0.12\\,\\text{N})\\bar{x}\\) .","solutionImages":[],"solutionTables":[],"discussion":"The direction of the force is the same as the initial direction of the force was in the previous example for a proton. However, because the current in a wire is confined to a wire, the direction in which the charges move does not change. Instead, the entire wire accelerates in the \\(\\bar{x}\\) -direction. The force on a current-carrying wire in a magnetic field is the basis of all electrical motors, as we will see in the upcoming sections."}],"snapLabs":[{"uid":"hsphys.ch20.sec01.lab01","title":"Refrigerator Magnets","text":"We know that like magnetic poles repel and unlike poles attract. See if you can show this for two refrigerator magnets. Will the magnets stick if you turn them over? Why do they stick to the refrigerator door anyway? What can you say about the magnetic properties of the refrigerator door near the magnet? Do refrigerator magnets stick to metal or plastic spoons? Do they stick to all types of metal?","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch20.sec01.feat01","type":"physics-in-action","title":"Magnetohydrodynamic Drive","text":"In Tom Clancy’s Cold War novel “The Hunt for Red October,” the Soviet Union built a submarine (see [Figure 20.1]) with a magnetohydrodynamic drive that was so silent it could not be detected by surface ships. The only conceivable purpose to build such a submarine was to give the Soviet Union first-strike capability, because this submarine could sneak close to the coast of the United States and fire its ballistic missiles, destroying key military and government installations to prevent an American counterattack.\nA Typhoon-class Russian ballistic-missile submarine on which the fictional submarine Red October was based.\nA magnetohydrodynamic drive is supposed to be silent because it has no moving parts. Instead, it uses the force experienced by charged particles that move in a magnetic field. The basic idea behind such a drive is depicted in [Figure 20.1]. Salt water flows through a channel that runs from the front to the back of the submarine. A magnetic field is applied horizontally across the channel, and a voltage is applied across the electrodes on the top and bottom of the channel to force a downward electric current through the water. The charge carriers are the positive sodium ions and the negative chlorine ions of salt. Using the right-hand rule, the force on the charge carriers is found to be toward the rear of the vessel. The accelerated charges collide with water molecules and transfer their momentum, creating a jet of water that is propelled out the rear of the channel. By Newton’s third law, the vessel experiences a force of equal magnitude, but in the opposite direction.\nA schematic drawing of a magnetohydrodynamic drive showing the water channel, the current direction, the magnetic field direction, and the resulting force.\nFortunately for all involved, it turns out that such a propulsion system is not very practical. Some back-of-the-envelope calculations show that, to power a submarine, either extraordinarily high magnetic fields or extraordinarily high electric currents would be required to obtain a reasonable thrust. In addition, prototypes of magnetohydrodynamic drives show that they are anything but silent. Electrolysis caused by running a current through salt water creates bubbles of hydrogen and oxygen, which makes this propulsion system quite noisy. The system also leaves a trail of chloride ions and metal chlorides that can easily be detected to locate the submarine. Finally, the chloride ions are extremely reactive and very quickly corrode metal parts, such as the electrode or the water channel itself. Thus, the Red October remains in the realm of fiction, but the physics involved is quite real.","images":[{"sourceId":"fs-id1167065975983","filename":"CNX_HSPhysics_20_01_sub.jpg","relativePath":"media/CNX_HSPhysics_20_01_sub.jpg","alt":"Typhoon-class Russian submarine."},{"sourceId":"fs-id1167065908450","filename":"CNX_HSPhysics_20_01_MHD.jpg","relativePath":"media/CNX_HSPhysics_20_01_MHD.jpg","alt":"Drawing of a magnetohydrodynamic dive showing the current (red arrow), the water channel, the magnetic field and the resulting force."}]}],"summaryPoints":["All magnets have two poles: a north pole and a south pole. If the magnet is free to move, its north pole orients itself toward the geographic North Pole of Earth, and the south pole orients itself toward the geographic South Pole of Earth.","A repulsive force occurs between the north poles of two magnets and likewise for two south poles. However, an attractive force occurs between the north pole of one magnet and the south pole of another magnet.","A charged particle moving through a magnetic field experiences a force whose direction is determined by the right-hand rule.","An electric current generates a magnetic field.","Electromagnets are magnets made by passing a current through a system of wires."],"glossary":[{"term":"Curie temperature","termVi":"Nhiệt độ Curie","definition":"well-defined temperature for ferromagnetic materials above which they cannot be magnetized","definitionVi":"Ngưỡng nhiệt độ mà nếu nung nóng vượt quá nó, nam châm vĩnh cửu mất hoàn toàn tính sắt từ.","memoryTipVi":"Với sắt là khoảng 770 °C."},{"term":"domain","termVi":"Miền từ hóa (Đô-men từ)","definition":"region within a magnetic material in which the magnetic poles of individual atoms are aligned","definitionVi":"Vùng vi mô trong chất sắt từ mà từ trường các nguyên tử sắp xếp song song cùng hướng.","memoryTipVi":"Khi các miền sắp xếp thẳng hàng → vật trở thành nam châm."},{"term":"electromagnet","termVi":"Nam châm điện","definition":"device that uses electric current to make a magnetic field","definitionVi":"Nam châm tạo bởi dòng điện chạy qua cuộn dây quấn quanh lõi sắt non (tắt điện là mất từ).","memoryTipVi":"Điều chỉnh được độ mạnh và đảo cực dễ dàng."},{"term":"electromagnetism","termVi":"Điện từ học","definition":"study of electric and magnetic phenomena","definitionVi":"Sự tương tác thống nhất giữa dòng điện và từ trường.","memoryTipVi":"Dòng điện sinh ra từ trường; từ trường biến thiên sinh ra dòng điện!"},{"term":"ferromagnetic","termVi":"Chất sắt từ (Sắt, Niken, Côban)","definition":"material such as iron, cobalt, nickel, or gadolinium that exhibits strong magnetic effects","definitionVi":"Vật liệu có thể bị từ hóa rất mạnh để trở thành nam châm.","memoryTipVi":"Fe (Sắt), Ni, Co."},{"term":"magnetic dipole","termVi":"Lưỡng cực từ","definition":"term that describes magnets because they always have two poles: north and south","definitionVi":"Cặp hai cực từ Bắc – Nam luôn đi đôi không thể tách rời.","memoryTipVi":"Mọi nam châm và vòng dây mang dòng điện đều là lưỡng cực từ."},{"term":"magnetic field","termVi":"Cảm ứng từ / Từ trường (B)","definition":"directional lines around a magnetic material that indicates the direction and magnitude of the magnetic force","definitionVi":"Trường lực tác dụng lên nam châm hoặc điện tích ĐANG CHUYỂN ĐỘNG (đơn vị SI: Tesla, T).","memoryTipVi":"Điện tích đứng yên (v = 0) KHÔNG chịu lực từ!"},{"term":"magnetic pole","termVi":"Từ cực (Cực Bắc N & Cực Nam S)","definition":"part of a magnet that exerts the strongest force on other magnets or magnetic material","definitionVi":"Hai đầu nam châm nơi lực từ mạnh nhất; cùng cực đẩy nhau, khác cực hút nhau.","memoryTipVi":"Cắt đôi thanh nam châm luôn tạo ra 2 nam châm mới đủ cả N và S — không tồn tại đơn cực từ!"},{"term":"magnetized","termVi":"Bị từ hóa","definition":"material that is induced to be magnetic or that is made into a permanent magnet","definitionVi":"Trạng thái chất sắt từ có các miền từ hóa sắp xếp cùng hướng tạo từ trường mạnh.","memoryTipVi":"Đập mạnh hoặc nung nóng làm mất từ tính."},{"term":"north pole","termVi":"Cực Bắc (N)","definition":"part of a magnet that orients itself toward the geographic North Pole of Earth","definitionVi":"Đầu kim la bàn luôn hướng về phía Bắc địa lý của Trái Đất.","memoryTipVi":"Thực chất cực Bắc địa lý của Trái Đất là một cực TỪ NAM nên mới hút cực Bắc kim la bàn!"},{"term":"permanent magnet","termVi":"Nam châm vĩnh cửu","definition":"material that retains its magnetic behavior for a long time, even when exposed to demagnetizing influences","definitionVi":"Vật giữ được từ tính lâu dài mà không cần dòng điện nuôi.","memoryTipVi":"Nam châm gắn cánh tủ lạnh."},{"term":"right-hand rule","termVi":"Quy tắc bàn tay phải","definition":"rule involving curling the right-hand fingers from one vector to another; the direction in which the right thumb points is the direction of the resulting vector","definitionVi":"Quy tắc xác định chiều đường sức từ quanh dây dẫn hoặc chiều lực từ F = qvB sinθ / F = ILB sinθ.","memoryTipVi":"Với điện tích ÂM (như electron), lực từ có chiều NGƯỢC LẠI kết quả quy tắc bàn tay phải!"},{"term":"solenoid","termVi":"Ống dây điện hình trụ (Solenoid)","definition":"uniform cylindrical coil of wire through which electric current is passed to produce a magnetic field","definitionVi":"Cuộn dây quấn xoắn lò xo nhiều vòng tạo từ trường đều ở bên trong lòng ống.","memoryTipVi":"B = μ₀ n I."},{"term":"south pole","termVi":"Cực Nam (S)","definition":"part of a magnet that orients itself toward the geographic South Pole of Earth","definitionVi":"Đầu nam châm hướng về phía Nam địa lý.","memoryTipVi":"Đường sức từ bên ngoài nam châm đi RA từ Bắc (N) và đi VÀO Nam (S)."}],"assessments":[{"uid":"hsphys.ch20.sec01.q002","sourceId":"fs-id1167065914129","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Describe methods to demagnetize a ferromagnet.","images":[],"choices":[{"label":"a","text":"by cooling, heating, or submerging in water"},{"label":"b","text":"by heating, hammering, and spinning it in external magnetic field"},{"label":"c","text":"by hammering, heating, and rubbing with cloth"},{"label":"d","text":"by cooling, submerging in water, or rubbing with cloth"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q005","sourceId":"fs-id1167062376996","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the magnitude of the force on an electron moving at 1.0 × 10 6 m/s perpendicular to a 1.0-T magnetic field?","images":[],"choices":[{"label":"a","text":"0.8 × 10 –13 N"},{"label":"b","text":"1.6 × 10 –14 N"},{"label":"c","text":"0.8 × 10 –14 N"},{"label":"d","text":"1.6 × 10 –13 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q006","sourceId":"fs-id1167065997196","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A straight 10 cm wire carries 0.40 A and is oriented perpendicular to a magnetic field. If the force on the wire is 0.022 N, what is the magnitude of the magnetic field?","images":[],"choices":[{"label":"a","text":"1.10 × 10 –2 T"},{"label":"b","text":"0.55 × 10 –2 T"},{"label":"c","text":"1.10 T"},{"label":"d","text":"0.55 T"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q008","sourceId":"fs-id1167064818023","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"If you place a compass at the three points in the figure, at which point will the needle experience the greatest torque? Why?","images":[{"sourceId":"eip-idm324695824","filename":"CNX_HSPhysics_20_01_004_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_004_img.jpg","alt":"An image of a bar magnet with the north side on top of the south side. Magnetic field lines are shown going from north to south. Point A is located above and close to the north side. Point B is right of the magnet between the two poles. Point C is below and away from the south side."}],"choices":[{"label":"a","text":"The density of the magnetic field is minimized at B, so the magnetic compass needle will experience the greatest torque at B."},{"label":"b","text":"The density of the magnetic field is minimized at C, so the magnetic compass needle will experience the greatest torque at C."},{"label":"c","text":"The density of the magnetic field is maximized at B, so the magnetic compass needle will experience the greatest torque at B."},{"label":"d","text":"The density of the magnetic field is maximized at A, so the magnetic compass needle will experience the greatest torque at A."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q010","sourceId":"fs-id1167065845979","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or false—It is not recommended to place credit cards with magnetic strips near permanent magnets.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q011","sourceId":"fs-id1167064709364","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or false—A square magnet can have sides that alternate between north and south poles.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q012","sourceId":"eip-id1166848795872","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"You move a compass in a circular plane around a planar magnet. The compass makes four complete revolutions. How many poles does the magnet have?","images":[],"choices":[{"label":"a","text":"two poles"},{"label":"b","text":"four poles"},{"label":"c","text":"eight poles"},{"label":"d","text":"12 poles"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q013","sourceId":"fs-id1167062376996","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the magnitude of the force on an electron moving at 1.0 × 10 6 m/s perpendicular to a 1.0-T magnetic field?","images":[],"choices":[{"label":"a","text":"0.8 × 10 –13 N"},{"label":"b","text":"1.6 × 10 –14 N"},{"label":"c","text":"0.8 × 10 –14 N"},{"label":"d","text":"1.6 × 10 –13 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q014","sourceId":"fs-id1167065997196","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A straight 10 cm wire carries 0.40 A and is oriented perpendicular to a magnetic field. If the force on the wire is 0.022 N, what is the magnitude of the magnetic field?","images":[],"choices":[{"label":"a","text":"1.10 × 10 –2 T"},{"label":"b","text":"0.55 × 10 –2 T"},{"label":"c","text":"1.10 T"},{"label":"d","text":"0.55 T"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q015","sourceId":"fs-id1167066103307","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A straight wire segment carries 0.25 A. What length would it need to be to exert a 4.0-mN force on a magnet that produces a uniform magnetic field of 0.015 T that is perpendicular to the wire?","images":[],"choices":[{"label":"a","text":"0.55 m"},{"label":"b","text":"1.1 m"},{"label":"c","text":"2.2 m"},{"label":"d","text":"4.4 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q016","sourceId":"fs-id1167065881582","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"For a magnet, a domain refers to ______.","images":[],"choices":[{"label":"a","text":"the region between the poles of the magnet"},{"label":"b","text":"the space around the magnet that is affected by the magnetic field"},{"label":"c","text":"the region within the magnet in which the magnetic poles of individual atoms are aligned"},{"label":"d","text":"the region from which the magnetic material is mined"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q017","sourceId":"fs-id1167065992612","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"In the region just outside the south pole of a magnet, the magnetic field lines ______.","images":[],"choices":[{"label":"a","text":"point away from the south pole"},{"label":"b","text":"go around the south pole"},{"label":"c","text":"are less concentrated than at the north pole"},{"label":"d","text":"point toward the south pole"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q020","sourceId":"eip-id1166847998230","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or false—If a magnet shatters into many small pieces, all the pieces will have north and south poles","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q023","sourceId":"fs-id1167064591015","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"To produce a magnetic field of 0.0020 T, what current is required in a 500-turn solenoid that is 25 cm long?","images":[],"choices":[{"label":"a","text":"0.80 A"},{"label":"b","text":"1.60 A"},{"label":"c","text":"80 A"},{"label":"d","text":"160 A"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q025","sourceId":"fs-id1167065954593","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":false,"prompt":"Using four solenoids of the same size, describe how to orient them and in which direction the current should flow to make a magnet with two opposite-facing north poles and two opposite-facing south poles.","images":[{"sourceId":"eip-idm370425712","filename":"CNX_HSPhysics_20_01_010a_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_010a_img.jpg","alt":"An image of four wire coils with a current flowing through each, creating a magnet in each case. Top coil is labeled N with arrow labeled I pointing toward end of coil. Right coil is labeled S with arrow labeled I pointing away from end of coil. Bottom coil is labeled N with arrow labeled I pointing away from end of coil. Left coil is labeled S with arrow labeled I pointing toward end of coil."},{"sourceId":"eip-idm320075120","filename":"CNX_HSPhysics_20_01_010b_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_010b_img.jpg","alt":"An image of four wire coils with a current flowing through each, creating a magnet in each case. Top coil is labeled S with arrow labeled I pointing away from end of coil. Right coil is labeled N with arrow labeled I pointing away from end of coil. Bottom coil is labeled S with arrow labeled I pointing away from end of coil. Left coil is labeled N with arrow labeled I pointing toward end of coil."},{"sourceId":"eip-idm367853680","filename":"CNX_HSPhysics_20_01_010c_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_010c_img.jpg","alt":"An image of four wire coils with a current flowing through each, creating a magnet in each case. Top coil is labeled N with arrow labeled I pointing toward end of coil. Right coil is labeled S with arrow labeled I pointing toward end of coil. Bottom coil is labeled N with arrow labeled I pointing away from end of coil. Left coil is labeled S with arrow labeled I pointing toward end of coil."},{"sourceId":"eip-idm379850480","filename":"CNX_HSPhysics_20_01_010d_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_010d_img.jpg","alt":"An image of four wire coils with a current flowing through each, creating a magnet in each case. Top coil is labeled S with arrow labeled I pointing toward end of coil. Right coil is labeled N with arrow labeled I pointing away from end of coil. Bottom coil is labeled S with arrow labeled I pointing toward end of coil. Left coil is labeled N with arrow labeled I pointing toward end of coil."}],"choices":[],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q026","sourceId":"fs-id1167062443813","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How far from a straight wire carrying 0.45 A is the magnetic field strength 0.040 T?","images":[],"choices":[{"label":"a","text":"0.23 µm"},{"label":"b","text":"0.72 µm"},{"label":"c","text":"2.3 µm"},{"label":"d","text":"7.2 µm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q027","sourceId":"fs-id1167065976170","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Summarize the properties of magnets.","images":[],"choices":[{"label":"a","text":"A magnet can attract metals like iron, nickel, etc., but cannot attract nonmetals like piece of plastic or wood, etc. If free to rotate, an elongated magnet will orient itself so that its north pole will face the magnetic south pole of Earth."},{"label":"b","text":"A magnet can attract metals like iron, nickel, etc., but cannot attract nonmetals like piece of plastic or wood, etc. If free to rotate, an elongated magnet will orient itself so that its north pole will face the magnetic north pole of Earth."},{"label":"c","text":"A magnet can attract metals like iron, nickel, etc., and nonmetals like piece of plastic or wood, etc. If free to rotate, an elongated magnet will orient itself so that its north pole will face the magnetic south pole of Earth."},{"label":"d","text":"A magnet can attract metals like iron, nickel, etc., and nonmetals like piece of plastic or wood, etc. If free to rotate, an elongated magnet will orient itself so that its north pole will face the magnetic north pole of Earth."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q028","sourceId":"fs-id1167062458492","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The magnetic field shown in the figure is formed by current flowing in two rings that intersect the page at the dots. Current flows into the page at the dots with crosses (right side) and out of the page at the dots with points (left side).\nWhere is the field strength the greatest and in what direction do the magnetic field lines point?","images":[{"sourceId":"fs-id1167063739513","filename":"CNX_HSPhysics_20_01_011_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_011_img.jpg","alt":"A figure of a magnet field being created by four wires. The left two wires are coming out of the page, while the right two are going into the page. The resulting magnetic field lines are close to vertical between the left two wires and the right two wires. On the left and right hand sides, the magnetic field lines are loops that center around the two nearest wires."}],"choices":[{"label":"a","text":"The magnetic field strength is greatest where the magnetic field lines are less dense; magnetic field lines points up the page."},{"label":"b","text":"The magnetic field strength is greatest where the magnetic field lines are most dense; magnetic field lines points up the page."},{"label":"c","text":"The magnetic field strength is greatest where the magnetic field lines are most dense; magnetic field lines points down the page."},{"label":"d","text":"The magnetic field strength is greatest where the magnetic field lines are less dense; magnetic field lines points down the page."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec01.q029","sourceId":"fs-id1167062559894","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The forces shown below are exerted on an electron as it moves through the magnetic field. In each case, what direction does the electron move?","images":[{"sourceId":"eip-idm206673136","filename":"CNX_HSPhysics_20_01_012_img.jpg","relativePath":"media/CNX_HSPhysics_20_01_012_img.jpg","alt":"Three images indicating the direction of a magnetic field and a force. Image a shows a force pointing upward while the magnetic field points out of the page. Image b shows a force pointing upward with a magnetic field pointing to the right. Image c shows a force pointing to the left and a magnetic field pointing out of the page."}],"choices":[{"label":"a","text":"(a) left to right, (b) out of the page, (c) upwards"},{"label":"b","text":"(a) left to right, (b) into the page, (c) downwards"},{"label":"c","text":"(a) right to left, (b) out of the page, (c) upwards"},{"label":"d","text":"(a) right to left, (b) into the page, (c) downwards"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":4,"subsectionCount":3,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":14,"assessmentCount":19}},{"uid":"hsphys.ch20.sec02","moduleId":"m54467","number":"20.2","slug":"motors-generators-and-transformers","title":"Motors, Generators, and Transformers","isIntroduction":false,"learningObjectives":["Explain how electric motors, generators, and transformers work","Explain how commercial electric power is produced, transmitted, and distributed"],"bilingualGuide":{"notebookSummaryVi":"Nguyên lý hoạt động của Động cơ điện (Motor), Máy phát điện (Generator) và Máy biến áp (Transformer: V_s/V_p = N_s/N_p).","wordProblemCues":[{"phraseEn":"step-up / step-down transformer","meaningVi":"Máy tăng áp (N_s > N_p) / Máy hạ áp (N_s < N_p)","mathNotation":"V_s/V_p = N_s/N_p"}],"commonTrapsVi":["Máy biến áp KHÔNG biến đổi được điện một chiều DC không đổi (vì không có sự biến thiên từ thông)!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch20.sec02.sub01","title":"Electric Motors, Generators, and Transformers","summaryVi":null,"paragraphs":["As we learned previously, a current-carrying wire in a magnetic field experiences a force—recall \\(F = IℓBsin\\theta\\) . Electric motors , which convert electrical energy into mechanical energy, are the most common application of magnetic force on current-carrying wires. Motors consist of loops of wire in a magnetic field. When current is passed through the loops, the magnetic field exerts a torque on the loops, which rotates a shaft. Electrical energy is converted to mechanical work in the process. [Figure 20.3] shows a schematic drawing of an electric motor.","Let us examine the force on each segment of the loop in [Figure 20.3] to find the torques produced about the axis of the vertical shaft—this will lead to a useful equation for the torque on the loop. We take the magnetic field to be uniform over the rectangular loop, which has width w and height \\(ℓ\\text{,}\\) as shown in the figure. First, consider the force on the top segment of the loop. To determine the direction of the force, we use the right-hand rule. The current goes from left to right into the page, and the magnetic field goes from left to right in the plane of the page. Curl your right fingers from the current vector to the magnetic field vector and your right thumb points down. Thus, the force on the top segment is downward, which produces no torque on the shaft. Repeating this analysis for the bottom segment—neglect the small gap where the lead wires go out—shows that the force on the bottom segment is upward, again producing no torque on the shaft.","Consider now the left vertical segment of the loop. Again using the right-hand rule, we find that the force exerted on this segment is perpendicular to the magnetic field, as shown in [Figure 20.3]. This force produces a torque on the shaft. Repeating this analysis on the right vertical segment of the loop shows that the force on this segment is in the direction opposite that of the force on the left segment, thereby producing an equal torque on the shaft. The total torque on the shaft is thus twice the toque on one of the vertical segments of the loop.","To find the magnitude of the torque as the wire loop spins, consider [Figure 20.3], which shows a view of the wire loop from above. Recall that torque is defined as \\(\\tau = rFsin\\theta \\text{,}\\) where F is the applied force, r is the distance from the pivot to where the force is applied, and θ is the angle between r and F . Notice that, as the loop spins, the current in the vertical loop segments is always perpendicular to the magnetic field. Thus, the equation \\(F = IℓBsin\\theta\\) gives the magnitude of the force on each vertical segment as \\(F = IℓB\\text{.}\\) The distance r from the shaft to where this force is applied is w /2, so the torque created by this force is","Because there are two vertical segments, the total torque is twice this, or","If we have a multiple loop with N turns, we get N times the torque of a single loop. Using the fact that the area of the loop is \\(A = wℓ\\text{;}\\) the expression for the torque becomes","This is the torque on a current-carrying loop in a uniform magnetic field. This equation can be shown to be valid for a loop of any shape.","From the equation \\(\\tau = NIABsin\\theta \\text{,}\\) we see that the torque is zero when \\(\\theta = 0\\text{.}\\) As the wire loop rotates, the torque increases to a maximum positive torque of \\(wℓB\\) when \\(\\theta = 90°\\text{.}\\) The torque then decreases back to zero as the wire loop rotates to \\(\\theta = 180°\\text{.}\\) From \\(\\theta = 180°\\) to \\(\\theta = 360°\\text{,}\\) the torque is negative. Thus, the torque changes sign every half turn, so the wire loop will oscillate back and forth.","For the coil to continue rotating in the same direction, the current is reversed as the coil passes through \\(\\theta = 0\\,\\text{and}\\theta = 180°\\) using automatic switches called brushes , as shown in [Figure 20.3].","Consider now what happens if we run the motor in reverse; that is, we attach a handle to the shaft and mechanically force the coil to rotate within the magnetic field, as shown in [Figure 20.3]. As per the equation \\(F = qvBsin\\theta\\) —where \\(\\theta\\) is the angle between the vectors \\(\\vec{v}\\) and \\(\\vec{B}\\text{—charges}\\) in the wires of the loop experience a magnetic force because they are moving in a magnetic field. Again using the right-hand rule, where we curl our fingers from vector \\(\\vec{v}\\) to vector \\(\\vec{B}\\), we find that charges in the top and bottom segments feel a force perpendicular to the wire, which does not cause a current. However, charges in the vertical wires experience forces parallel to the wire, causing a current to flow through the wire and through an external circuit if one is connected. A device such as this that converts mechanical energy into electrical energy is called a generator .","Because current is induced only in the side wires, we can find the induced emf by only considering these wires. As explained in Induced Current in a Wire , motional emf in a straight wire moving at velocity v through a magnetic field B is \\(ε = Bℓv\\text{,}\\) where the velocity is perpendicular to the magnetic field. In the generator, the velocity makes an angle \\(\\theta\\) with B (see [Figure 20.3]), so the velocity component perpendicular to B is \\(vsin\\theta \\text{.}\\) Thus, in this case, the emf induced on each vertical wire segment is \\(ε = Bℓvsin\\theta \\text{,}\\) and they are in the same direction. The total emf around the loop is then","Although this expression is valid, it does not give the emf as a function of time. To find how the emf evolves in time, we assume that the coil is rotated at a constant angular velocity \\(\\omega \\text{.}\\) The angle \\(\\theta\\) is related to the angular velocity by \\(\\theta = \\omega t\\text{,}\\) so that","Recall that tangential velocity v is related to angular velocity \\(\\omega\\) by \\(v = r\\omega \\text{.}\\) Here, \\(r = w/2\\), so that \\(v = (w/2)\\omega\\) and","Noting that the area of the loop is \\(A = ℓw\\) and allowing for N wire loops, we find that","is the emf induced in a generator coil of N turns and area A rotating at a constant angular velocity \\(\\omega\\) in a uniform magnetic field B . This can also be expressed as","where","is the maximum (peak) emf.","[Figure 20.3] shows a generator connected to a light bulb and a graph of the emf vs. time. Note that the emf oscillates from a positive maximum of \\({ε}_{0}\\) to a negative maximum of \\({-E}_{0}\\text{.}\\) In between, the emf goes through zero, which means that zero current flows through the light bulb at these times. Thus, the light bulb actually flickers on and off at a frequency of 2 f , because there are two zero crossings per period. Since alternating current such as this is used in homes around the world, why do we not notice the lights flickering on and off? In the United States, the frequency of alternating current is 60 Hz, so the lights flicker on and off at a frequency of 120 Hz. This is faster than the refresh rate of the human eye, so you don’t notice the flicker of the lights. Also, other factors prevent various different types of light bulbs from switching on and off so fast, so the light output is smoothed out a bit.","Use this simulation to discover how an electrical generator works. Control the water supply that makes a water wheel turn a magnet. This induces an emf in a nearby wire coil, which is used to light a light bulb. You can also replace the light bulb with a voltmeter, which allows you to see the polarity of the voltage, which changes from positive to negative.","Set the number of wire loops to three, the bar-magnet strength to about 50 percent, and the loop area to 100 percent. Note the maximum voltage on the voltmeter. Assuming that one major division on the voltmeter is 5V, what is the maximum voltage when using only a single wire loop instead of three wire loops?","In real life, electric generators look a lot different than the figures in this section, but the principles are the same. The source of mechanical energy that turns the coil can be falling water—hydropower—steam produced by the burning of fossil fuels, or the kinetic energy of wind. [Figure 20.3] shows a cutaway view of a steam turbine; steam moves over the blades connected to the shaft, which rotates the coil within the generator.","Another very useful and common device that exploits magnetic induction is called a transformer . Transformers do what their name implies—they transform voltages from one value to another; the term voltage is used rather than emf because transformers have internal resistance. For example, many cell phones, laptops, video games, power tools, and small appliances have a transformer built into their plug-in unit that changes 120 V or 240 V AC into whatever voltage the device uses. [Figure 20.3] shows two different transformers. Notice the wire coils that are visible in each device. The purpose of these coils is explained below.","[Figure 20.3] shows a laminated-coil transformer , which is based on Faraday’s law of induction and is very similar in construction to the apparatus Faraday used to demonstrate that magnetic fields can generate electric currents. The two wire coils are called the primary and secondary coils . In normal use, the input voltage is applied across the primary coil, and the secondary produces the transformed output voltage. Not only does the iron core trap the magnetic field created by the primary coil, but also its magnetization increases the field strength, which is analogous to how a dielectric increases the electric field strength in a capacitor. Since the input voltage is AC, a time-varying magnetic flux is sent through the secondary coil, inducing an AC output voltage.","For the transformer shown in [Figure 20.3], the output voltage \\({V}_{\\text{S}}\\) from the secondary coil depends almost entirely on the input voltage \\({V}_{\\text{P}}\\) across the primary coil and the number of loops in the primary and secondary coils. Faraday’s law of induction for the secondary coil gives its induced output voltage \\({V}_{\\text{S}}\\) to be","where \\({N}_{\\text{S}}\\) is the number of loops in the secondary coil and \\(\\Delta \\text{Φ}/\\Delta t\\) is the rate of change of magnetic flux. The output voltage equals the induced emf (\nV\nS\n=\nε\nS\n), provided coil resistance is small—a reasonable assumption for transformers. The cross-sectional area of the coils is the same on each side, as is the magnetic field strength, and so \\(\\Delta \\text{Φ/Δ}t\\) is the same on each side. The input primary voltage \\({V}_{\\text{P}}\\) is also related to changing flux by","Taking the ratio of these last two equations yields the useful relationship","This is known as the transformer equation. It simply states that the ratio of the secondary voltage to the primary voltage in a transformer equals the ratio of the number of loops in secondary coil to the number of loops in the primary coil."],"figures":[{"sourceId":"fs-id1167064933153","filename":"CNX_HSPhysics_20_03_elecmotor.jpg","relativePath":"media/CNX_HSPhysics_20_03_elecmotor.jpg","alt":"Schematic drawing of an electric motor, including a horizontal magnetic field and a vertical loop of wire through which a current is passed. Torque is exerted on the wire, turning the shaft to which the magnetic field is attached."},{"sourceId":"fs-id1167065764178","filename":"CNX_HSPhysics_20_03_toploop.jpg","relativePath":"media/CNX_HSPhysics_20_03_toploop.jpg","alt":"View of the wire loop from the previous figure from above."},{"sourceId":"fs-id1167065793310","filename":"CNX_HSPhysics_20_03_brushes.jpg","relativePath":"media/CNX_HSPhysics_20_03_brushes.jpg","alt":"Part (a) shows the torque remaining clockwise when the brushes reverse the current as the coil passes through 0. Part (b) shows the coil rotating continuously in a clockwise direction with the current reversing each one-half revolution."},{"sourceId":"fs-id1167065838947","filename":"CNX_HSPhysics_20_03_generator.jpg","relativePath":"media/CNX_HSPhysics_20_03_generator.jpg","alt":"Image of a generator, including a coil that rotates and changes the magnetic flux, which induces an emf and drives current through an external circuit."},{"sourceId":"fs-id1167064648188","filename":"CNX_HSPhysics_20_03_3dgen.jpg","relativePath":"media/CNX_HSPhysics_20_03_3dgen.jpg","alt":"The emf in a straight wire moving at velocity v through a magnetic field B, where the velocity is perpendicular to the magnetic field."},{"sourceId":"fs-id1167062579393","filename":"CNX_HSPhysics_20_03_light.jpg","relativePath":"media/CNX_HSPhysics_20_03_light.jpg","alt":"A generator connected to a light bulb and a graph of the emf vs. time."},{"sourceId":"fs-id1167064951682","filename":"CNX_HSPhysics_20_03_turbine.jpg","relativePath":"media/CNX_HSPhysics_20_03_turbine.jpg","alt":"Close-up of a large industrial turbine's open casing, revealing multiple stages of compressor blades during maintenance or assembly. The intricate design highlights the complex engineering of power generation."},{"sourceId":"fs-id1167064769441","filename":"CNX_HSPhysics_20_03_trans.jpg","relativePath":"media/CNX_HSPhysics_20_03_trans.jpg","alt":"Part (a) shows a laminated-core transformer. Part (b) shows a toroidal transformer."},{"sourceId":"fs-id1167065028460","filename":"CNX_HSPhysics_20_03_lamcoil.jpg","relativePath":"media/CNX_HSPhysics_20_03_lamcoil.jpg","alt":"Schematic of a simple transformer with two coils wound around a laminated ferromagnetic core."}],"tables":[]},{"uid":"hsphys.ch20.sec02.sub02","title":"Transmission of Electrical Power","summaryVi":null,"paragraphs":["Transformers are widely used in the electric power industry to increase voltages—called step-up transformers—before long-distance transmission via high-voltage wires. They are also used to decrease voltages—called step-down transformers—to deliver power to homes and businesses. The overwhelming majority of electric power is generated by using magnetic induction, whereby a wire coil or copper disk is rotated in a magnetic field. The primary energy required to rotate the coils or disk can be provided by a variety of means. Hydroelectric power plants use the kinetic energy of water to drive electric generators. Coal or nuclear power plants create steam to drive steam turbines that turn the coils. Other sources of primary energy include wind, tides, or waves on water.","Once power is generated, it must be transmitted to the consumer, which often means transmitting power over hundreds of kilometers. To do this, the voltage of the power plant is increased by a step-up transformer, that is stepped up, and the current decreases proportionally because","The lower current \\({I}_{\\text{transmitted}}\\) in the transmission wires reduces the Joule losses , which is heating of the wire due to a current flow. This heating is caused by the small, but nonzero, resistance \\({R}_{\\text{wire}}\\) of the transmission wires. The power lost to the environment through this heat is","which is proportional to the current squared in the transmission wire. This is why the transmitted current \\({I}_{\\text{transmitted}}\\) must be as small as possible and, consequently, the voltage must be large to transmit the power \\({P}_{\\text{transmitted}}\\text{⋅}\\)","Voltages ranging from 120 to 700 kV are used for transmitting power over long distances. The voltage is stepped up at the exit of the power station by a step-up transformer, as shown in [Figure 20.3].","Once the power has arrived at a population or industrial center, the voltage is stepped down at a substation to between 5 and 30 kV. Finally, at individual homes or businesses, the power is stepped down again to 120, 240, or 480 V. Each step-up and step-down transformation is done with a transformer designed based on Faradays law of induction."],"figures":[{"sourceId":"fs-id1167065927082","filename":"CNX_HSPhysics_20_03_grid.jpg","relativePath":"media/CNX_HSPhysics_20_03_grid.jpg","alt":"Cartoon of the electric grid, from power plant to a home, travelling through transformers and over transmission lines."}],"tables":[]},{"uid":"hsphys.ch20.sec02.sub03","title":"Performance Task","summaryVi":null,"paragraphs":["Your family takes a trip to Cuba, and rents an old car to drive into the countryside to see the sights. Unfortunately, the next morning you find yourself deep in the countryside and the car won’t start because the battery is too weak. Wanting to jump-start the car, you open the hood and find that you can’t tell which battery terminal is positive and which is negative. However, you do have a bar magnet with the north and south poles labeled and you manage to find a short wire. How do you use these to determine which terminal is which? For starters, how do you determine the direction of a magnetic field around a current-carrying wire? And in which direction will the force be on another magnet placed in this field? Do you need to worry about the sign of the mobile charge carriers in the wire?"],"figures":[],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch20.sec02.feat01","type":"physics-in-action","title":"Magnetic Rope Memory","text":"To send men to the moon, the Apollo program had to design an onboard computer system that would be robust, consume little power, and be small enough to fit onboard the spacecraft. In the 1960s, when the Apollo program was launched, entire buildings were regularly dedicated to housing computers whose computing power would be easily outstripped by today’s most basic handheld calculator.\nTo address this problem, engineers at MIT and a major defense contractor turned to magnetic rope memory , which was an offshoot of a similar technology used prior to that time for creating random access memories. Unlike random access memory, magnetic rope memory was read-only memory that contained not only data but instructions as well. Thus, it was actually more than memory: It was a hard-wired computer program.\nThe components of magnetic rope memory were wires and iron rings—which were called cores . The iron cores served as transformers, such as that shown in the previous figure. However, instead of looping the wires multiple times around the core, individual wires passed only a single time through the cores, making these single-turn transformers. Up to 63 word wires could pass through a single core, along with a single bit wire. If a word wire passed through a given core, a voltage pulse on this wire would induce an emf in the bit wire, which would be interpreted as a one . If the word wire did not pass through the core, no emf would be induced on the bit wire, which would be interpreted as a zero .\nEngineers would create programs that would be hard wired into these magnetic rope memories. The wiring process could take as long as a month to complete as workers painstakingly threaded wires through some cores and around others. If any mistakes were made either in the programming or the wiring, debugging would be extraordinarily difficult, if not impossible.\nThese modules did their job quite well. They are credited with correcting an astronaut mistake in the lunar landing procedure, thereby allowing Apollo 11 to land on the moon. It is doubtful that Michael Faraday ever imagined such an application for magnetic induction when he discovered it.","images":[]}],"summaryPoints":["Electric motors contain wire loops in a magnetic field. Current is passed through the wire loops, which forces them to rotate in the magnetic field. The current is reversed every half rotation so that the torque on the loop is always in the same direction.","Electric generators contain wire loops in a magnetic field. An external agent provides mechanical energy to force the loops to rotate in the magnetic field, which produces an AC voltage that drives an AC current through the loops.","Transformers contain a ring made of magnetic material and, on opposite sides of the ring, two windings of wire wrap around the ring. A changing current in one wire winding creates a changing magnetic field, which is trapped in the ring and thus goes through the second winding and induces an emf in the second winding. The voltage in the second winding is proportional to the ratio of the number of loops in each winding.","Transformers are used to step up and step down the voltage for power transmission.","Over long distances, electric power is transmitted at high voltage to minimize the current and thereby minimize the Joule losses due to resistive heating."],"glossary":[{"term":"electric motor","termVi":"Động cơ điện","definition":"device that transforms electrical energy into mechanical energy","definitionVi":"Thiết bị biến đổi ĐIỆN năng thành CƠ năng (nhờ lực từ làm quay khung dây).","memoryTipVi":"Motor: Điện → Quay."},{"term":"generator","termVi":"Máy phát điện","definition":"device that transforms mechanical energy into electrical energy","definitionVi":"Thiết bị biến đổi CƠ năng thành ĐIỆN năng nhờ hiện tượng cảm ứng điện từ.","memoryTipVi":"Generator: Quay → Điện."},{"term":"transformer","termVi":"Máy biến áp","definition":"device that transforms voltages from one value to another","definitionVi":"Thiết bị tăng hoặc hạ điện áp xoay chiều AC theo tỉ lệ số vòng dây: V_s / V_p = N_s / N_p.","memoryTipVi":"⚠️ Máy biến áp CHỈ hoạt động với dòng điện xoay chiều (AC), không hoạt động với DC ổn định!"}],"assessments":[{"uid":"hsphys.ch20.sec02.q004","sourceId":"fs-id1167065704157","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What should be the ratio of the number of output coils to the number of input coil in a step-up transformer to increase the voltage fivefold?","images":[],"choices":[{"label":"a","text":"The ratio is five times."},{"label":"b","text":"The ratio is 10 times."},{"label":"c","text":"The ratio is 15 times."},{"label":"d","text":"The ratio is 20 times."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q006","sourceId":"eip-id1166848797613","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What is a voltage transformer?","images":[],"choices":[{"label":"a","text":"A transformer is a device that transforms current to voltage."},{"label":"b","text":"A transformer is a device that transforms voltages from one value to another."},{"label":"c","text":"A transformer is a device that transforms resistance of wire to voltage."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q007","sourceId":"eip-id1166846436366","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Why is electric power transmitted at high voltage?","images":[],"choices":[{"label":"a","text":"To increase the current for the transmission"},{"label":"b","text":"To reduce energy loss during transmission"},{"label":"c","text":"To increase resistance during transmission"},{"label":"d","text":"To reduce resistance during transmission"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q009","sourceId":"fs-id1167066159070","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Explain why power is transmitted over long distances at high voltages.","images":[],"choices":[{"label":"a","text":"P lost = I transmitted V transmitted , so to maximize current, the voltage must be maximized"},{"label":"b","text":"P transmitted = I transmitted V transmitted , so to maximize current, the voltage must be maximized"},{"label":"c","text":"P lost = I transmitted V transmitted , so to minimize current, the voltage must be maximized"},{"label":"d","text":"P transmitted = I transmitted V transmitted , so to minimize current, the voltage must be maximized"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q010","sourceId":"fs-id1167065964879","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"An electrical generator ________.","images":[],"choices":[{"label":"a","text":"is a generator powered by electricity"},{"label":"b","text":"must be turned by hand"},{"label":"c","text":"converts other sources of power into electrical power"},{"label":"d","text":"uses magnetism to create electrons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q011","sourceId":"fs-id1167064948237","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A step-up transformer increases the","images":[],"choices":[{"label":"a","text":"voltage from power lines for use in homes"},{"label":"b","text":"current from the power lines for use in homes"},{"label":"c","text":"current from the electrical generator for transmission along power lines"},{"label":"d","text":"voltage from the electrical power plant for transmission along power lines"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q012","sourceId":"eip-id1166848893975","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What would be the effect on the torque of an electric motor of doubling the width of the current loop in the motor?","images":[],"choices":[{"label":"a","text":"Torque remains the same."},{"label":"b","text":"Torque is doubled."},{"label":"c","text":"Torque is quadrupled."},{"label":"d","text":"Torque is halved."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q014","sourceId":"fs-id1167064961163","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A laminated-coil transformer has a wire coiled 12 times around one of its sides. How many coils should you wrap around the opposite side to get a voltage output that is one half of the input voltage? Explain.","images":[],"choices":[{"label":"a","text":"six output coils because the ratio of output to input voltage is the same as the ratio of number of output coils to input coils"},{"label":"b","text":"12 output coils because the ratio of output to input voltage is the same as the ratio of number of output coils to input coils"},{"label":"c","text":"24 output coils because the ratio of output to input voltage is half the ratio of the number of output coils to input coils"},{"label":"d","text":"36 output coils because the ratio of output to input voltage is three times the ratio of the number of output coils to input coils"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q015","sourceId":"fs-id1167064529215","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Explain why long-distance electrical power lines are designed to carry very high voltages.","images":[],"choices":[{"label":"a","text":"P transmitted = I transmitted> 2 R wire and P lost = I transmitted V transmitted , so V must be low to make the current transmitted as high as possible."},{"label":"b","text":"P transmitted = I transmitted> 2 R wire and P lost = I lost V lost , so V must be low to make the current transmitted as high as possible."},{"label":"c","text":"P transmitted = I transmitted> 2 R wire and P lost = I transmitted V transmitted , so V must be high to make the current transmitted as low as possible"},{"label":"d","text":"P lost = I transmitted 2 R wire and P transmitted = I transmitted V transmitted , so V must be high to make the current transmitted as low as possible."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec02.q019","sourceId":"fs-id1167065029197","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Your friend tells you that power lines must carry a maximum current because P = I 2 R , where R is the resistance of the transmission line. What do you tell her?","images":[],"choices":[{"label":"a","text":"P transmitted = I transmitted 2 R wire and P lost = I transmitted V transmitted , so I must be high to reduce power lost due to transmission."},{"label":"b","text":"P lost = I transmitted 2 R wire and P lost = I transmitted V transmitted , so I must be high to reduce power lost due to transmission."},{"label":"c","text":"P transmitted = I transmitted 2 R wire and P lost = I transmitted V transmitted , so I must be low to reduce power lost due to transmission."},{"label":"d","text":"P lost = I transmitted 2 R wire and P lost = I transmitted V transmitted , so I must be low to reduce power lost due to transmission."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":0,"subsectionCount":3,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":3,"assessmentCount":10}},{"uid":"hsphys.ch20.sec03","moduleId":"m54456","number":"20.3","slug":"electromagnetic-induction","title":"Electromagnetic Induction","isIntroduction":false,"learningObjectives":["Explain how a changing magnetic field produces a current in a wire","Calculate induced electromotive force and current"],"bilingualGuide":{"notebookSummaryVi":"Từ thông (Φ = BA cosθ), Định luật cảm ứng điện từ Faraday (ε = -N ΔΦ/Δt) và Định luật Lenz (dấu trừ chống lại nguyên nhân sinh ra nó).","wordProblemCues":[{"phraseEn":"Faraday’s law & Lenz’s law","meaningVi":"Suất điện động cảm ứng & Chiều dòng cảm ứng","mathNotation":"ε = -N ΔΦ/Δt"}],"commonTrapsVi":["Góc θ trong Φ = BA cosθ là góc giữa B và PHÁP TUYẾN khung dây (nếu B vuông góc mặt khung thì θ = 0° → cos 0° = 1)!"]},"keyEquations":[{"name":"magnetic flux","formula":"\\(\\text{Φ} = BAcos\\theta\\)"},{"name":"emf","formula":"\\(ε = - N\\frac{\\Delta \\text{Φ}}{\\Delta t}\\)"}],"subsections":[{"uid":"hsphys.ch20.sec03.sub01","title":"Changing Magnetic Fields","summaryVi":null,"paragraphs":["In the preceding section, we learned that a current creates a magnetic field. If nature is symmetrical, then perhaps a magnetic field can create a current. In 1831, some 12 years after the discovery that an electric current generates a magnetic field, English scientist Michael Faraday (1791–1862) and American scientist Joseph Henry (1797–1878) independently demonstrated that magnetic fields can produce currents. The basic process of generating currents with magnetic fields is called induction ; this process is also called magnetic induction to distinguish it from charging by induction, which uses the electrostatic Coulomb force.","When Faraday discovered what is now called Faraday’s law of induction, Queen Victoria asked him what possible use was electricity. “Madam,” he replied, “What good is a baby?” Today, currents induced by magnetic fields are essential to our technological society. The electric generator—found in everything from automobiles to bicycles to nuclear power plants—uses magnetism to generate electric current. Other devices that use magnetism to induce currents include pickup coils in electric guitars, transformers of every size, certain microphones, airport security gates, and damping mechanisms on sensitive chemical balances.","One experiment Faraday did to demonstrate magnetic induction was to move a bar magnet through a wire coil and measure the resulting electric current through the wire. A schematic of this experiment is shown in [Figure 20.2]. He found that current is induced only when the magnet moves with respect to the coil. When the magnet is motionless with respect to the coil, no current is induced in the coil, as in [Figure 20.2]. In addition, moving the magnet in the opposite direction (compare [Figure 20.2] with [Figure 20.2]) or reversing the poles of the magnet (compare [Figure 20.2] with [Figure 20.2]) results in a current in the opposite direction.","Try this simulation to see how moving a magnet creates a current in a circuit. A light bulb lights up to show when current is flowing, and a voltmeter shows the voltage drop across the light bulb. Try moving the magnet through a four-turn coil and through a two-turn coil. For the same magnet speed, which coil produces a higher voltage?"],"figures":[{"sourceId":"fs-id1167067044773","filename":"CNX_HSPhysics_20_02_ammeter.jpg","relativePath":"media/CNX_HSPhysics_20_02_ammeter.jpg","alt":"Movement of a magnet relative to a coil as measured by an ammeter."}],"tables":[]},{"uid":"hsphys.ch20.sec03.sub02","title":"Induced Electromotive Force","summaryVi":null,"paragraphs":["If a current is induced in the coil, Faraday reasoned that there must be what he called an electromotive force pushing the charges through the coil. This interpretation turned out to be incorrect; instead, the external source doing the work of moving the magnet adds energy to the charges in the coil. The energy added per unit charge has units of volts, so the electromotive force is actually a potential. Unfortunately, the name electromotive force stuck and with it the potential for confusing it with a real force. For this reason, we avoid the term electromotive force and just use the abbreviation emf , which has the mathematical symbol \\(ε\\text{.}\\) The emf may be defined as the rate at which energy is drawn from a source per unit current flowing through a circuit. Thus, emf is the energy per unit charge added by a source, which contrasts with voltage, which is the energy per unit charge released as the charges flow through a circuit.","To understand why an emf is generated in a coil due to a moving magnet, consider [Figure 20.2], which shows a bar magnet moving downward with respect to a wire loop. Initially, seven magnetic field lines are going through the loop (see left-hand image). Because the magnet is moving away from the coil, only five magnetic field lines are going through the loop after a short time \\(\\Delta t\\) (see right-hand image). Thus, when a change occurs in the number of magnetic field lines going through the area defined by the wire loop, an emf is induced in the wire loop. Experiments such as this show that the induced emf is proportional to the rate of change of the magnetic field. Mathematically, we express this as","where \\(\\Delta B\\) is the change in the magnitude in the magnetic field during time \\(\\Delta t\\) and A is the area of the loop.","Note that magnetic field lines that lie in the plane of the wire loop do not actually pass through the loop, as shown by the left-most loop in [Figure 20.2]. In this figure, the arrow coming out of the loop is a vector whose magnitude is the area of the loop and whose direction is perpendicular to the plane of the loop. In [Figure 20.2], as the loop is rotated from \\(\\theta = 90°\\)\nto \\(\\theta = 0°\\text{,}\\) the contribution of the magnetic field lines to the emf increases. Thus, what is important in generating an emf in the wire loop is the component of the magnetic field that is perpendicular to the plane of the loop, which is \\(Bcos\\theta \\text{.}\\)","This is analogous to a sail in the wind. Think of the conducting loop as the sail and the magnetic field as the wind. To maximize the force of the wind on the sail, the sail is oriented so that its surface vector points in the same direction as the winds, as in the right-most loop in [Figure 20.2]. When the sail is aligned so that its surface vector is perpendicular to the wind, as in the left-most loop in [Figure 20.2], then the wind exerts no force on the sail.","Thus, taking into account the angle of the magnetic field with respect to the area, the proportionality \\(ε∝\\Delta B/\\Delta t\\) becomes","Another way to reduce the number of magnetic field lines that go through the conducting loop in [Figure 20.2] is not to move the magnet but to make the loop smaller. Experiments show that changing the area of a conducting loop in a stable magnetic field induces an emf in the loop. Thus, the emf produced in a conducting loop is proportional to the rate of change of the product of the perpendicular magnetic field and the loop area","where \\(Bcos\\theta\\) is the perpendicular magnetic field and A is the area of the loop. The product \\(BAcos\\theta\\) is very important. It is proportional to the number of magnetic field lines that pass perpendicularly through a surface of area A . Going back to our sail analogy, it would be proportional to the force of the wind on the sail. It is called the magnetic flux and is represented by Φ .","The unit of magnetic flux is the weber (Wb), which is magnetic field per unit area, or T/m 2 . The weber is also a volt second (Vs).","The induced emf is in fact proportional to the rate of change of the magnetic flux through a conducting loop.","Finally, for a coil made from N loops, the emf is N times stronger than for a single loop. Thus, the emf induced by a changing magnetic field in a coil of N loops is","The last question to answer before we can change the proportionality into an equation is “In what direction does the current flow?” The Russian scientist Heinrich Lenz (1804–1865) explained that the current flows in the direction that creates a magnetic field that tries to keep the flux constant in the loop. For example, consider again [Figure 20.2]. The motion of the bar magnet causes the number of upward-pointing magnetic field lines that go through the loop to decrease. Therefore, an emf is generated in the loop that drives a current in the direction that creates more upward-pointing magnetic field lines. By using the right-hand rule, we see that this current must flow in the direction shown in the figure. To express the fact that the induced emf acts to counter the change in the magnetic flux through a wire loop, a minus sign is introduced into the proportionality \\(ε∝\\Delta \\text{Φ}/\\Delta t\\text{.}\\), which gives Faraday’s law of induction.","Lenz’s law is very important. To better understand it, consider [Figure 20.2], which shows a magnet moving with respect to a wire coil and the direction of the resulting current in the coil. In the top row, the north pole of the magnet approaches the coil, so the magnetic field lines from the magnet point toward the coil. Thus, the magnetic field \\({\\vec{B}}_{\\text{mag}} = {B}_{\\text{mag}}(\\bar{x})\\) pointing to the right increases in the coil. According to Lenz’s law, the emf produced in the coil will drive a current in the direction that creates a magnetic field \\({\\vec{B}}_{\\text{coil}} = {B}_{\\text{coil}}( - \\bar{x})\\) inside the coil pointing to the left. This will counter the increase in magnetic flux pointing to the right. To see which way the current must flow, point your right thumb in the desired direction of the magnetic field \\({\\vec{B}}_{\\text{coil,}}\\) and the current will flow in the direction indicated by curling your right fingers. This is shown by the image of the right hand in the top row of [Figure 20.2]. Thus, the current must flow in the direction shown in Figure 4(a) .","In Figure 4(b) , the direction in which the magnet moves is reversed. In the coil, the right-pointing magnetic field \\({\\vec{B}}_{\\text{mag}}\\) due to the moving magnet decreases. Lenz’s law says that, to counter this decrease, the emf will drive a current that creates an additional right-pointing magnetic field \\({\\vec{B}}_{\\text{coil}}\\) in the coil. Again, point your right thumb in the desired direction of the magnetic field, and the current will flow in the direction indicate by curling your right fingers ( Figure 4(b) ).","Finally, in Figure 4(c) , the magnet is reversed so that the south pole is nearest the coil. Now the magnetic field \\({\\vec{B}}_{\\text{mag}}\\) points toward the magnet instead of toward the coil. As the magnet approaches the coil, it causes the left-pointing magnetic field in the coil to increase. Lenz’s law tells us that the emf induced in the coil will drive a current in the direction that creates a magnetic field pointing to the right. This will counter the increasing magnetic flux pointing to the left due to the magnet. Using the right-hand rule again, as indicated in the figure, shows that the current must flow in the direction shown in Figure 4(c) .","This simulation proposes several activities. For now, click on the tab Pickup Coil, which presents a bar magnet that you can move through a coil. As you do so, you can see the electrons move in the coil and a light bulb will light up or a voltmeter will indicate the voltage across a resistor. Note that the voltmeter allows you to see the sign of the voltage as you move the magnet about. You can also leave the bar magnet at rest and move the coil, although it is more difficult to observe the results."],"figures":[{"sourceId":"fs-id1167063739513","filename":"CNX_HSPhysics_20_02_twomags.jpg","relativePath":"media/CNX_HSPhysics_20_02_twomags.jpg","alt":"Part (a) shows seven magnetic field lines going through a wire loop. Part (b) shows that after a period of time, only five magnetic field lines are going through the loop."},{"sourceId":"fs-id1167066970835","filename":"CNX_HSPhysics_20_02_loops.jpg","relativePath":"media/CNX_HSPhysics_20_02_loops.jpg","alt":"As a wire loop is rotated through a magnetic field, it generates an emf. The dots show where the magnetic field lines intersect the plane defined by the loop."},{"sourceId":"fs-id1167066879643","filename":"CNX_HSPhysics_20_02_LL.jpg","relativePath":"media/CNX_HSPhysics_20_02_LL.jpg","alt":"A bar magnet with a pickup coil to its right. Parts (a) through (c) show what happens as the two are moved toward each other with respect to electron movement and current flow."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch20.sec03.ex01","number":"20.3.1","title":"EMF Induced in Conducing Coil by Moving Magnet","problem":"Imagine a magnetic field goes through a coil in the direction indicated in [Figure 20.2]. The coil diameter is 2.0 cm. If the magnetic field goes from 0.020 to 0.010 T in 34 s, what is the direction and magnitude of the induced current? Assume the coil has a resistance of 0.1 Ω.\nA coil through which passes a magnetic field B .","problemImages":[{"sourceId":"fs-id1167067166137","filename":"CNX_HSPhysics_20_02_coil.jpg","relativePath":"media/CNX_HSPhysics_20_02_coil.jpg","alt":"A coil with a magnetic field running through it."}],"strategy":"Use the equation \\(ε = - N\\Delta \\text{Φ}/\\Delta t\\) to find the induced emf in the coil, where Δ t = 34 s . Counting the number of loops in the solenoid, we find it has 16 loops, so \\(N = 16\\text{.}\\) Use the equation \\(\\text{Φ} = BAcos\\theta\\) to calculate the magnetic flux\nΦ = B A cos θ = B π\n(\nd\n2\n)\n2\n,\nwhere d is the diameter of the solenoid and we have used \\(cos0° = 1\\text{.}\\) Because the area of the solenoid does not vary, the change in the magnetic of the flux through the solenoid is\nΔ Φ = Δ B π\n(\nd\n2\n)\n2\n.\nOnce we find the emf, we can use Ohm’s law, \\(ε = IR\\text{,}\\) to find the current.\nFinally, Lenz’s law tells us that the current should produce a magnetic field that acts to oppose the decrease in the applied magnetic field. Thus, the current should produce a magnetic field to the right.","solution":"Combining equations \\(ε = - N\\Delta \\text{Φ}/\\Delta t\\)\nand \\(\\text{Φ} = BAcos\\theta\\)\ngives\n\\(ε = - N\\frac{\\Delta \\text{Φ}}{\\Delta t} = - N\\frac{\\Delta B\\pi {d}^{2}}{4\\,\\Delta t}\\text{.}\\)\nSolving Ohm’s law for the current and using this result gives\n\\(I = \\frac{ε}{R} = - N\\frac{\\Delta B\\pi {d}^{2}}{4R\\Delta t} = -16\\frac{(-0.010\\,\\text{T})\\pi {(0.020\\,\\text{m})}^{2}}{4(0.10\\,\\Omega )(34\\,\\text{s})} = 15\\,\\mu \\text{A}\\text{.}\\) Lenz’s law tells us that the current must produce a magnetic field to the right. Thus, we point our right thumb to the right and curl our right fingers around the solenoid. The current must flow in the direction in which our fingers are pointing, so it enters at the left end of the solenoid and exits at the right end.","solutionImages":[],"solutionTables":[],"discussion":"Let’s see if the minus sign makes sense in Faraday’s law of induction. Define the direction of the magnetic field to be the positive direction. This means the change in the magnetic field is negative, as we found above. The minus sign in Faraday’s law of induction negates the negative change in the magnetic field, leaving us with a positive current. Therefore, the current must flow in the direction of the magnetic field, which is what we found.\nNow try defining the positive direction to be the direction opposite that of the magnetic field, that is positive is to the left in [Figure 20.2]. In this case, you will find a negative current. But since the positive direction is to the left, a negative current must flow to the right, which again agrees with what we found by using Lenz’s law."},{"uid":"hsphys.ch20.sec03.ex02","number":"20.3.2","title":"Magnetic Induction due to Changing Circuit Size","problem":"The circuit shown in [Figure 20.2] consists of a U-shaped wire with a resistor and with the ends connected by a sliding conducting rod. The magnetic field filling the area enclosed by the circuit is constant at 0.01 T. If the rod is pulled to the right at speed \\(v = 0.50\\,\\text{m/s,}\\) what current is induced in the circuit and in what direction does the current flow?\nA slider circuit. The magnetic field is constant and the rod is pulled to the right at speed v . The changing area enclosed by the circuit induces an emf in the circuit.","problemImages":[{"sourceId":"fs-id1167067057624","filename":"CNX_HSPhysics_20_02_slider.jpg","relativePath":"media/CNX_HSPhysics_20_02_slider.jpg","alt":"A slider circuit consisting of a U-shaped wire with a resistor and the ends connected by a sliding conducting rod."}],"strategy":"We again use Faraday’s law of induction, \\(ε = - N\\frac{\\Delta \\text{Φ}}{\\Delta t}\\text{,}\\) although this time the magnetic field is constant and the area enclosed by the circuit changes. The circuit contains a single loop, so \\(N = 1\\text{.}\\) The rate of change of the area is \\(\\frac{\\Delta A}{\\Delta t} = vℓ\\text{.}\\) Thus the rate of change of the magnetic flux is\n\\(\\frac{\\Delta \\text{Φ}}{\\Delta t} = \\frac{\\Delta (BAcos\\theta )}{\\Delta t} = B\\frac{\\Delta A}{\\Delta t} = Bvℓ\\text{,}\\)\nwhere we have used the fact that the angle \\(\\theta\\) between the area vector and the magnetic field is 0°. Once we know the emf, we can find the current by using Ohm’s law. To find the direction of the current, we apply Lenz’s law.","solution":"Faraday’s law of induction gives\n\\(ε = - N\\frac{\\Delta \\text{Φ}}{\\Delta t} = - Bvℓ\\text{.}\\)\nSolving Ohm’s law for the current and using the previous result for emf gives\n\\(I = \\frac{ε}{R} = \\frac{- Bvℓ}{R} = \\frac{- (0.010\\,\\text{T})(0.50\\,\\text{m/s})(0.10\\,\\text{m})}{20\\,\\Omega} = 25\\,\\mu \\text{A}\\text{.}\\)\nAs the rod slides to the right, the magnetic flux passing through the circuit increases. Lenz’s law tells us that the current induced will create a magnetic field that will counter this increase. Thus, the magnetic field created by the induced current must be into the page. Curling your right-hand fingers around the loop in the clockwise direction makes your right thumb point into the page, which is the desired direction of the magnetic field. Thus, the current must flow in the clockwise direction around the circuit.","solutionImages":[],"solutionTables":[],"discussion":"Is energy conserved in this circuit? An external agent must pull on the rod with sufficient force to just balance the force on a current-carrying wire in a magnetic field—recall that \\(F = IℓBsin\\theta \\text{.}\\) The rate at which this force does work on the rod should be balanced by the rate at which the circuit dissipates power. Using \\(F = IℓBsin\\theta \\text{,}\\) the force required to pull the wire at a constant speed v is\n\\({F}_{\\text{pull}} = IℓBsin\\theta = IℓB\\text{,}\\)\nwhere we used the fact that the angle \\(\\theta\\) between the current and the magnetic field is \\(90°\\text{.}\\) Inserting our expression above for the current into this equation gives\n\\({F}_{\\text{pull}} = IℓB = - \\frac{Bvℓ}{R}(ℓB) = - \\frac{{B}^{2}v{ℓ}^{2}}{R}\\text{.}\\)\nThe power contributed by the agent pulling the rod is \\({F}_{\\text{pull}}v\\text{, or}\\)\n\\({P}_{\\text{pull}} = {F}_{\\text{pull}}v = - \\frac{{B}^{2}{v}^{2}{ℓ}^{2}}{R}\\text{.}\\)\nThe power dissipated by the circuit is\n\\({P}_{\\text{dissipated}} = {I}^{2}R = {(\\frac{- Bvℓ}{R})}^{2}R = \\frac{{B}^{2}{v}^{2}{ℓ}^{2}}{R}\\text{.}\\)\nWe thus see that \\({P}_{\\text{pull}} + {P}_{\\text{dissipated}} = 0\\text{,}\\) which means that power is conserved in the system consisting of the circuit and the agent that pulls the rod. Thus, energy is conserved in this system."}],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":["Faraday’s law of induction states that a changing magnetic flux that occurs within an area enclosed by a conducting loop induces an electric current in the loop.","Lenz’ law states that an induced current flows in the direction such that it opposes the change that induced it."],"glossary":[{"term":"emf","termVi":"Suất điện động cảm ứng (ε)","definition":"rate at which energy is drawn from a source per unit current flowing through a circuit","definitionVi":"Điện áp sinh ra do sự biến thiên từ thông theo Định luật Faraday: ε = -N · ΔΦ / Δt (đơn vị Volt, V).","memoryTipVi":"Viết tắt của Electromotive Force (nhưng đơn vị là Volt, không phải lực Newton!)."},{"term":"induction","termVi":"Hiện tượng cảm ứng điện từ","definition":"rate at which energy is drawn from a source per unit current flowing through a circuit","definitionVi":"Hiện tượng xuất hiện suất điện động (và dòng điện cảm ứng) khi từ thông qua mạch kín biến thiên.","memoryTipVi":"Khám phá vĩ đại của Michael Faraday."},{"term":"magnetic flux","termVi":"Từ thông (Φ = B·A·cosθ)","definition":"component of the magnetic field perpendicular to the surface area through which it passes and multiplied by the area","definitionVi":"Lượng đường sức từ xuyên qua một diện tích A (đơn vị Weber, Wb).","memoryTipVi":"θ là góc giữa vectơ B và PHÁP TUYẾN của mặt phẳng khung dây!"}],"assessments":[{"uid":"hsphys.ch20.sec03.q003","sourceId":"fs-id1167063961434","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"The magnetic flux through a single wire loop changes from 3.5 Wb to 1.5 Wb in 2.0 s. What emf is induced in the loop?","images":[],"choices":[{"label":"a","text":"–2.0 V"},{"label":"b","text":"–1.0 V"},{"label":"c","text":"+1.0 V"},{"label":"d","text":"+2.0 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q004","sourceId":"fs-id1167066859936","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the emf for a 10-turn coil through which the flux changes at 10 Wb/s?","images":[],"choices":[{"label":"a","text":"–100 V"},{"label":"b","text":"–10 V"},{"label":"c","text":"+10 V"},{"label":"d","text":"+100 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q005","sourceId":"fs-id1167063832124","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Yes or no—Is an emf induced in the coil shown when it is stretched? If so, state why and give the direction of the induced current.","images":[{"sourceId":"eip-idm375588176","filename":"CNX_HSPhysics_20_02_004_img.jpg","relativePath":"media/CNX_HSPhysics_20_02_004_img.jpg","alt":"Two images of a circular wire embedded in a magnetic field that is pointing into the page. The left figure shows the circular wire enclosing four of the magnetic field points with two hands on either end pulling on the wire initially shaped like a circle. The image on the right shows the same wire stretched out into an ellipse."}],"choices":[{"label":"a","text":"No, because induced current does not depend upon the area of the coil."},{"label":"b","text":"Yes, because area of the coil decreases; the direction of the induced current is counterclockwise."},{"label":"c","text":"Yes, because area of the coil decreases; the direction of the induced current is clockwise."},{"label":"d","text":"Yes, because the area of the coil does not change; the direction of the induced current is clockwise."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q007","sourceId":"eip-id1166851337430","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Explain how magnetic flux can be zero when the magnetic field is not zero.","images":[],"choices":[{"label":"a","text":"If angle between magnetic field and area vector is 0°, then its sine is also zero, which means that there is zero flux."},{"label":"b","text":"If angle between magnetic field and area vector is 45°, then its sine is also zero, which means that there is zero flux."},{"label":"c","text":"If angle between magnetic field and area vector is 60°, then its cosine is also zero, which means that there is zero flux."},{"label":"d","text":"If the angle between magnetic field and area vector is 90°, then its cosine is also zero, which means that there is zero flux."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q008","sourceId":"fs-id1167063871011","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"To obtain power from the current in the wire of your vacuum cleaner, you place a loop of wire near it to obtain an induced emf. How do you place and orient the loop?","images":[],"choices":[{"label":"a","text":"A loop of wire should be placed nearest to the vacuum cleaner wire to maximize the magnetic flux through the loop."},{"label":"b","text":"A loop of wire should be placed farthest to the vacuum cleaner wire to maximize the magnetic flux through the loop."},{"label":"c","text":"A loop of wire should be placed perpendicular to the vacuum cleaner wire to maximize the magnetic flux through the loop."},{"label":"d","text":"A loop of wire should be placed at angle greater than 90° to the vacuum cleaner wire to maximize the magnetic flux through the loop."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q009","sourceId":"eip-id1166848666253","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"A magneto is a device that creates a spark across a gap by creating a large voltage across the gap. To do this, the device spins a magnet very quickly in front of a wire coil, with the ends of the wires forming the gap. Explain how this creates a sufficiently large voltage to produce a spark.","images":[],"choices":[{"label":"a","text":"The electric field in the coil increases rapidly due to spinning of magnet which creates an emf in the coil that is proportional to the rate of change of the magnetic flux."},{"label":"b","text":"The magnetic field in the coil changes rapidly due to spinning of magnet which creates an emf in the coil that is proportional to the rate of change of the magnetic flux."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q011","sourceId":"fs-id1167063961434","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The magnetic flux through a single wire loop changes from 3.5 Wb to 1.5 Wb in 2.0 s. What emf is induced in the loop?","images":[],"choices":[{"label":"a","text":"–2.0 V"},{"label":"b","text":"–1.0 V"},{"label":"c","text":"+1.0 V"},{"label":"d","text":"+2.0 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q012","sourceId":"fs-id1167066859936","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the emf for a 10-turn coil through which the flux changes at 10 Wb/s?","images":[],"choices":[{"label":"a","text":"–100 V"},{"label":"b","text":"–10 V"},{"label":"c","text":"+10 V"},{"label":"d","text":"+100 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q013","sourceId":"fs-id1167063735162","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the current in a wire loop of resistance 10 Ω through which the magnetic flux changes from zero to 10 Wb in 1.0 s?","images":[],"choices":[{"label":"a","text":"–100 A"},{"label":"b","text":"–2.0 A"},{"label":"c","text":"–1.0 A"},{"label":"d","text":"+1.0 A"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q014","sourceId":"fs-id1167066984531","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An emf is induced by rotating a 1,000 turn, 20.0 cm diameter coil in Earth’s 5.00 × 10 –5 T magnetic field. What average emf is induced, given the plane of the coil is originally perpendicular to Earth’s field and is rotated to be parallel to the field in 10.0 ms?","images":[],"choices":[{"label":"a","text":"–1.6 × 10 -4 V"},{"label":"b","text":"+1.6 × 10 -4 V"},{"label":"c","text":"+1.6 × 10 -1 V"},{"label":"d","text":"–1.6 × 10 -1 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q015","sourceId":"fs-id1167066844928","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What does emf stand for?","images":[],"choices":[{"label":"a","text":"electromotive force"},{"label":"b","text":"electro motion force"},{"label":"c","text":"electromagnetic factor"},{"label":"d","text":"electronic magnetic factor"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q018","sourceId":"eip-id1166851124116","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or false—If you drop a bar magnet through a copper tube, it induces an electric current in the tube.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q020","sourceId":"fs-id1167063699239","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"The plane of a square wire circuit with side 4.0 cm long is at an angle of 45° with respect to a uniform magnetic field of 0.25 T. The wires have a resistance per unit length of 0.2. If the field drops to zero in 2.5 s, what magnitude current is induced in the square circuit?","images":[],"choices":[{"label":"a","text":"35 µA"},{"label":"b","text":"87.5 µA"},{"label":"c","text":"3.5 mA"},{"label":"d","text":"35 A"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q021","sourceId":"fs-id1167063734265","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Yes or no—If a bar magnet moves through a wire loop as shown in the figure, is a current induced in the loop? Explain why or why not.","images":[{"sourceId":"fs-id1164561190006","filename":"CNX_HSPhysics_20_02_006_img.jpg","relativePath":"media/CNX_HSPhysics_20_02_006_img.jpg","alt":"This figure shows a round circle representing a wire loop and a bar magnet with an arrow pointing upward as it moves through the wire loop. The south and north poles run parallel with the surface area enclosed by the loop."}],"choices":[{"label":"a","text":"No, because the net magnetic field passing through the loop is zero."},{"label":"b","text":"No, because the net magnetic field passing through the loop is nonzero."},{"label":"c","text":"Yes, because the net magnetic field passing through the loop is zero."},{"label":"d","text":"Yes, because the net magnetic field line passing through the loop is nonzero."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q022","sourceId":"fs-id1167067166280","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the magnetic flux through an equilateral triangle with side 60 cm long and whose plane makes a 60° angle with a uniform magnetic field of 0.33 T?","images":[],"choices":[{"label":"a","text":"0.045 Wb"},{"label":"b","text":"0.09 Wb"},{"label":"c","text":"0.405 Wb"},{"label":"d","text":"4.5 Wb"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q023","sourceId":"fs-id1167067144817","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"When you insert a copper ring between the poles of two bar magnets as shown in the figure, do the magnets exert an attractive or repulsive force on the ring? Explain your reasoning.","images":[{"sourceId":"fs-id1164564989059","filename":"CNX_HSPhysics_20_02_007_img.jpg","relativePath":"media/CNX_HSPhysics_20_02_007_img.jpg","alt":"The figure shows south pole of a bar magnet at the top of the figure and a north pole of a bar magnet at the bottom of the figure. A copper ring is approaching and almost inside the location between the two magnetic poles as shown by an arrow. The copper ring runs in and out of the page so that the maximum surface area enclosed by the loop cannot be seen in the figure."}],"choices":[{"label":"a","text":"Magnets exert an attractive force, because magnetic field due to induced current is repulsed by the magnetic field of the magnets."},{"label":"b","text":"Magnets exert an attractive force, because magnetic field due to induced current is attracted by the magnetic field of the magnets."},{"label":"c","text":"Magnets exert a repulsive force, because magnetic field due to induced current is repulsed by the magnetic field of the magnets."},{"label":"d","text":"Magnets exert a repulsive force, because magnetic field due to induced current is attracted by the magnetic field of the magnets."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch20.sec03.q024","sourceId":"fs-id1167063642046","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The figure shows a uniform magnetic field passing through a closed wire circuit. The wire circuit rotates at an angular frequency of about the axis shown by the dotted line in the figure.\nWhat is an expression for the magnetic flux through the circuit as a function of time?","images":[{"sourceId":"eip-idm370482272","filename":"CNX_HSPhysics_20_02_008_img.jpg","relativePath":"media/CNX_HSPhysics_20_02_008_img.jpg","alt":"The diagram has two rectangles that are folded at the middle at about 90 degrees. This creates an upper flap of the rectangle that points to the right and a lower flap that points straight down. The variable lowercase L labels the length of the lower flap of the rectangle. The label lowercase L over 2 is on the height of the lower flap of the rectangle. The label lowercase L over 2 is also on the width of the upper flap of the rectangle. Vector B labels four downward-pointing, diagonal arrows that each pass through the fold in the rectangle at a 45 degree angle."}],"choices":[{"label":"a","text":"expression for the magnetic flux through the circuit Φ( t ) = BA cos ⁡ωt"},{"label":"b","text":"expression for the magnetic flux through the circuit \\(\\text{Φ}(t) = \\sqrt{2}BA\\text{cos}\\omega t\\)"},{"label":"c","text":"expression for the magnetic flux through the circuit \\(\\text{Φ}(t) = \\sqrt{3}BA\\text{cos}\\omega t\\)"},{"label":"d","text":"expression for the magnetic flux through the circuit Φ( t ) = 2 BA cos ωt"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":2,"subsectionCount":2,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":3,"assessmentCount":17}}],"summary":{"totalSections":4,"totalKeyEquations":6,"totalWorkedExamples":4,"totalSnapLabs":1,"totalGlossaryTerms":20,"totalAssessments":46,"referencedMediaCount":49},"qualityGate":{"passed":true,"checkedUids":64,"errors":[],"warnings":[]}};
